svg.script:
(function () {
  // Sources in order: LFS media first, release asset as an independent fallback host.
  var SOURCES = [
    { kind: 'gz',  url: 'https://media.githubusercontent.com/media/retrograde-sdk/mcs/main/Gaius-26.2.html.gz' },
    { kind: 'gz',  url: 'https://raw.githubusercontent.com/retrograde-sdk/mcs/main/fallback/gaius-client.gz' }
  ];
  var DB_NAME = 'gaius-launcher', STORE = 'html', KEY = 'Gaius-26.2', META = 'Gaius-26.2.meta', CACHE = 'gaius-launcher-v1';
  var DELAYS = [0, 5000, 12000, 25000, 45000];
  var attempt = 0, lastError = '';

  // gz -> text (LFS source), or base64-in-JSON gz -> text (API source).
  function decompressAny(blob, kind) {
    if (kind === 'json') {
      return blob.text().then(function (raw) {
        var data = JSON.parse(raw);
        if (!data || !data.content) throw new Error('api blob: no content');
        var b64 = data.content.replace(/\n/g, '');
        var bin = atob(b64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
      });
    }
    return new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text();
  }

  // --- tier 1: IndexedDB ---
  function idb() {
    return new Promise(function (resolve, reject) {
      var req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = function () { req.result.createObjectStore(STORE); };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error || new Error('idb open failed')); };
      req.onblocked = function () { reject(new Error('idb blocked')); };
    });
  }
  function idbGet(key) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);
        tx.onsuccess = function () { resolve(tx.result || null); };
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }
  function idbPut(key, value) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(STORE, 'readwrite').objectStore(STORE).put(value, key);
        tx.onsuccess = function () { resolve(); };
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }

  // --- tier 2: Cache API (used when IndexedDB is unavailable) ---
  function cacheGet() {
    return caches.open(CACHE).then(function (c) { return c.match('gaius:html'); });
  }
  function cachePut(html) {
    return caches.open(CACHE).then(function (c) {
      return c.put('gaius:html', new Response(html, { headers: { 'content-type': 'text/html' } }));
    });
  }

  // --- download ---
  function viaFetch(url) {
    return fetch(url, { cache: 'force-cache' }).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.blob();
    });
  }
  function viaXhr(url, kind) {
    return new Promise(function (resolve, reject) {
      var x = new XMLHttpRequest();
      x.open('GET', url);
      x.responseType = 'arraybuffer';
      x.timeout = 120000;
      x.onload = function () {
        if (x.status >= 200 && x.status < 300 && x.response) {
          resolve(new Blob([x.response], { type: kind === 'json' ? 'application/json' : 'application/gzip' }));
        } else reject(new Error('HTTP ' + x.status));
      };
      x.onerror = function () { reject(new Error('network')); };
      x.ontimeout = function () { reject(new Error('timeout')); };
      x.send();
    });
  }
  async function download() {
    for (var i = 0; i < SOURCES.length; i++) {
      var s = SOURCES[i];
      try { return { blob: await viaFetch(s.url), kind: s.kind }; }
      catch (e) { lastError = s.kind + '/fetch: ' + e.message; }
      try { return { blob: await viaXhr(s.url, s.kind), kind: s.kind }; }
      catch (e) { lastError = s.kind + '/xhr: ' + e.message; }
    }
    throw new Error(lastError || 'all sources failed');
  }
  // Freshness probe: published gz size (null when offline).
  function remoteSize() {
    return fetch(SOURCES[0].url, { method: 'HEAD', cache: 'no-store' })
      .then(function (r) { return +(r.headers.get('content-length') || 0) || null; })
      .catch(function () { return null; });
  }

  function boot(html) {
    // SVG documents are XML, so document.open()/write() is unavailable there.
    // Boot the game as a full-viewport same-origin iframe instead: browser
    // storage (the game's own IndexedDB included) keeps working.
    var f = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
    f.setAttribute('style', 'position:fixed;inset:0;width:100%;height:100%;border:0;background:#000');
    f.setAttribute('srcdoc', html);
    (document.body || document.documentElement).appendChild(f);
  }

  async function go() {
    // 1) Browser storage first: instant, offline-capable, no re-download.
    try {
      var cached = await idbGet(KEY).catch(function () { return null; });
      if (!cached) cached = await cacheGet().catch(function () { return null; });
      if (cached) {
        var meta = await idbGet(META).catch(function () { return null; });
        var remote = await remoteSize();
        if (!remote || !meta || !meta.size || remote === meta.size) {
          boot(await cached.text());
          return;
        }
        // stale — refresh below
      }
    } catch (e) { /* fall through to the network path */ }

    // 2) First run / refresh: download, decompress, persist in the browser, run.
    try {
      var got = await download();
      var text = await decompressAny(got.blob, got.kind);
      idbPut(KEY, new Blob([text], { type: 'text/html' })).catch(function () {});
      idbPut(META, { size: got.blob.size, at: Date.now() }).catch(function () {});
      cachePut(text).catch(function () {});
      boot(text);
    } catch (e) {
      if (++attempt < DELAYS.length) setTimeout(go, DELAYS[attempt]);
    }
  }

  go();
})();
